from model import Summary
def run(data, limit):
 frames = []
 offset = 0
 length = len(data)

 while offset < length:
  start = offset
  size = data[offset]
  if size > limit:
   return Summary(frames, start, 3)

  payload_start = start + 1
  checksum_offset = payload_start + size
  if checksum_offset >= length:
   return Summary(frames, start, 1)

  payload = data[payload_start:checksum_offset]
  if sum(payload) % 256 != data[checksum_offset]:
   return Summary(frames, start, 2)

  frames.append(payload)
  offset = checksum_offset + 1

 return Summary(frames, length, 0)

